<?php
function o_hidden(string $name,string|int $value):void{echo '<input type="hidden" name="'.e($name).'" value="'.e((string)$value).'">';}
function o_form(string $view,string $action,array $hidden=[]):void{echo '<form method="post" action="'.e(m_admin_url($view)).'">';o_hidden('csrf',csrf_token());o_hidden('action',$action);foreach($hidden as $k=>$v){o_hidden($k,$v);}}
function o_input(string $name,string $label,string $type='text',string $value='',bool $required=false):void{static $n=0;$id='op_'.++$n;echo '<label for="'.$id.'">'.e($label).'</label>';if($type==='textarea'){echo '<textarea id="'.$id.'" name="'.e($name).'" rows="5" maxlength="20000"'.($required?' required':'').'>'.e($value).'</textarea>';}else{echo '<input id="'.$id.'" name="'.e($name).'" type="'.e($type).'" value="'.e($value).'"'.($required?' required':'').($type==='password'?' autocomplete="'.($name==='passphrase'?'off':'current-password').'" maxlength="256"':'').($type==='number'?' min="1"':'').'>';}}
function o_select(string $name,string $label,array $choices,string $selected=''):void{static $n=0;$id='select_'.++$n;echo '<label for="'.$id.'">'.e($label).'</label><select name="'.e($name).'" id="'.$id.'">';foreach($choices as $key=>$text){echo '<option value="'.e((string)$key).'"'.((string)$key===$selected?' selected':'').'>'.e($text).'</option>';}echo '</select>';}
function o_button(string $text):void{echo '<button class="button">'.e($text).'</button></form>';}
