<section class="panel"><h2>Retention-expired records</h2><?php o_form('privacy','retention_refresh');o_input('confirm_code','Your current private code','password','',true);o_button('Initialize up to 100 missing closure/deadline retention dates');?><p>No automatic deletion runs. Holds prevent anonymization; selected production records require separate contractual review and a verified deletion request. Limits: 20 due records per category per view. Process records deliberately, then revisit the list.</p><?php foreach($due as $scope=>$subjects):?><h3><?= e(ucfirst($scope)) ?></h3><?php foreach($subjects as $subject):?><p>#<?= (int)$subject['id'] ?> · <?= e($subject['identifier'].' · '.$subject['due']) ?></p><?php endforeach;endforeach;?><h3>Current holds / completed anonymizations</h3><?php foreach($holds as $hold):?><p><?= e($hold['scope'].' #'.$hold['subject_id'].' · hold '.$hold['legal_hold'].' · '.($hold['anonymized_at']??'not anonymized')) ?><br><?= e($hold['hold_reason']) ?></p><?php endforeach;?></section>
