<section class="panel"><h2>Physical attachment deletion</h2><?php foreach($fileJobs as $job):?><p><?= e($job['state']) ?>: <?= (int)$job['n'] ?></p><?php endforeach;?><p>Access is revoked immediately by anonymization. Physical files remain pending until this bounded cleanup succeeds. Review failed counts and backup retention.</p><?php o_form('privacy','files_remove');o_input('confirm_code','Your current private code','password','',true);o_button('Process up to 20 file deletions');?></section>
